<section class="components-page form-elements-page">
  <div class="row g-4">
    <div class="col-xl-6"><div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Select2</h5></div><div class="card-body form-stack"><div><label class="form-label" for="selectBasic">Basic select</label><select id="selectBasic" class="form-select"><option selected>Option 1</option><option>Option 2</option><option>Option 3</option></select></div><div><label class="form-label" for="selectGrouped">Option groups</label><select id="selectGrouped" class="form-select"><optgroup label="Europe"><option>London</option><option>Paris</option><option>Rome</option></optgroup><optgroup label="Asia"><option>Jakarta</option><option>Tokyo</option><option>Singapore</option></optgroup></select></div><div><label class="form-label" for="selectMultiple">Multiple select</label><select id="selectMultiple" class="form-select" multiple><option selected>Dashboard</option><option selected>Analytics</option><option>CRM</option><option>eCommerce</option><option>Academy</option></select></div></div></div></div>
    <div class="col-xl-6"><div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Tagify</h5></div><div class="card-body form-stack"><div><label class="form-label" for="tagsBasicInput">Basic tags</label><div class="tag-input" data-tag-input><div class="tag-list"><span class="tag-pill">Design<button type="button" aria-label="Remove Design">×</button></span><span class="tag-pill">Dashboard<button type="button" aria-label="Remove Dashboard">×</button></span></div><input id="tagsBasicInput" type="text" placeholder="Add tag"></div></div><div><label class="form-label" for="tagsEmailInput">Email tags</label><div class="tag-input" data-tag-input><div class="tag-list"><span class="tag-pill">admin@example.com<button type="button" aria-label="Remove admin@example.com">×</button></span></div><input id="tagsEmailInput" type="email" placeholder="name@example.com"></div></div></div></div></div>
  </div>
  <div class="card app-card component-section"><div class="card-header"><h5 class="card-title mb-0">Select States</h5></div><div class="card-body"><div class="row g-4"><div class="col-md-4"><label class="form-label" for="selectDisabled">Disabled</label><select id="selectDisabled" class="form-select" disabled><option>Disabled select</option></select></div><div class="col-md-4"><label class="form-label" for="selectValid">Valid</label><select id="selectValid" class="form-select is-valid"><option selected>Valid option</option></select><div class="valid-feedback">Looks good.</div></div><div class="col-md-4"><label class="form-label" for="selectInvalid">Invalid</label><select id="selectInvalid" class="form-select is-invalid"><option selected>Choose an option</option></select><div class="invalid-feedback">Please select a value.</div></div></div></div></div>
